INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind dynamische Testverfahren dasselbe wie statische Tests?', 2, '[{"text": "Nein", "correct": true, "because": "Ausführung vs. Analyse"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen dynamische Testverfahren?', 3, '[{"text": "Fehler während der Ausführung finden", "correct": true, "because": "Laufzeitprüfung"}, {"text": "Code ohne Ausführung prüfen", "correct": false, "because": "Statische Tests"}, {"text": "Hardware testen", "correct": false, "because": "Softwarefokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zu dynamischen Testverfahren?', 5, '[{"text": "Black-Box-Testing", "correct": true, "because": "Funktionalität prüfen"}, {"text": "White-Box-Testing", "correct": true, "because": "Interner Code"}, {"text": "Code-Reviews", "correct": false, "because": "Statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dynamische Tests laufen zur Laufzeit. b) Sie prüfen nur Quellcode.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Codeprüfung ist statisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei dynamischen Testverfahren?', 4, '[{"text": "Testfälle", "correct": false, "because": "Grundlage der Tests"}, {"text": "Laufzeitverhalten", "correct": false, "because": "Kern der Methode"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob dynamische Tests ohne Ausführung möglich sind?', 2, '[{"text": "Nein", "correct": true, "because": "Laufzeit nötig"}, {"text": "Ja", "correct": false, "because": "Statische Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testart ist ein dynamisches Verfahren?', 3, '[{"text": "Unit-Testing", "correct": true, "because": "Code ausführen"}, {"text": "Code-Inspektion", "correct": false, "because": "Statisch"}, {"text": "Syntaxprüfung", "correct": false, "because": "Statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten dynamische Testverfahren?', 5, '[{"text": "Laufzeitfehler finden", "correct": true, "because": "Ausführung prüfen"}, {"text": "Realitätsnahe Tests", "correct": true, "because": "Echte Nutzung"}, {"text": "Code ohne Ausführung", "correct": false, "because": "Statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dynamische Tests prüfen Verhalten. b) Sie ersetzen statische Tests. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für dynamische Testverfahren?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Ausführung nötig"}, {"text": "Testfälle", "correct": false, "because": "Prüfgrundlage"}, {"text": "Papierdokumente", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind dynamische Tests immer automatisiert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch manuell möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testarten gehören zu dynamischen Verfahren?', 4, '[{"text": "Integrationstests", "correct": true, "because": "Komponenten ausführen"}, {"text": "Systemtests", "correct": true, "because": "Gesamtsystem prüfen"}, {"text": "Code-Analyse", "correct": false, "because": "Statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass dynamische Tests keine Fehler finden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Laufzeitfehler aufdecken"}, {"text": "Ja", "correct": false, "because": "Fehlererkennung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei dynamischen Testverfahren?', 3, '[{"text": "Testabdeckung", "correct": true, "because": "Fehler finden"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dynamische Tests prüfen Funktionalität. b) Sie analysieren nur Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Code-Analyse statisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge nutzen dynamische Testverfahren?', 5, '[{"text": "Test-Frameworks", "correct": true, "because": "Z. B. JUnit"}, {"text": "Debugger", "correct": true, "because": "Laufzeitanalyse"}, {"text": "Texteditor", "correct": false, "because": "Kein Testtool"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei dynamischen Testverfahren unwichtig?', 3, '[{"text": "Testdaten", "correct": false, "because": "Prüfgrundlage"}, {"text": "Ausführung", "correct": false, "because": "Kernmerkmal"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können dynamische Tests Laufzeitfehler finden?', 3, '[{"text": "Ja", "correct": true, "because": "Ausführung prüfen"}, {"text": "Nein", "correct": false, "because": "Fehlererkennung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob dynamische Tests Hardware prüfen?', 2, '[{"text": "Nein", "correct": true, "because": "Softwarefokus"}, {"text": "Ja", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für dynamische Testverfahren zentral?', 4, '[{"text": "Programmausführung", "correct": true, "because": "Laufzeitprüfung"}, {"text": "Code ohne Ausführung", "correct": false, "because": "Statisch"}, {"text": "Manuelle Analyse", "correct": false, "because": "Automatisierung möglich"}]');
